import dev.wowforever.app.ui.*;
import dev.wowforever.app.ui.journal.*;
import java.awt.*;
import java.nio.file.*;
import java.util.*;

/** Existing profile generated by prior genuine GUI job. No network/build or cold-first-run claim. */
public final class GeneratedLibraryStartupAcceptance {
 public static void main(String[] args)throws Exception{
  JournalSnapshots.out=Path.of(args[1]);Files.createDirectories(JournalSnapshots.out);var report=JournalSnapshots.report;report.add("Exact JAR SHA256: "+JournalSnapshots.hash(Path.of(args[0])));report.add("EXISTING GENERATED PROFILE startup/capture only; prior genuine GUI job produced this app-owned selected library. No new provider download or cold-build claim.");int exit=0;
  try{
   JournalSnapshots.check(System.getProperty("wowforever.database")==null&&System.getProperty("wowforever.data.dir")==null,"Generated-profile startup uses no database or asset override");dev.wowforever.app.Main.main(new String[0]);ResearchAcceptance.until(()->JournalSnapshots.edt(()->{JournalSnapshots.frame=Arrays.stream(Window.getWindows()).filter(window->window instanceof MainFrame&&window.isShowing()).map(MainFrame.class::cast).findFirst().orElse(null);return JournalSnapshots.frame!=null&&JournalSnapshots.all(JournalSnapshots.frame).stream().anyMatch(JournalHomePage.class::isInstance);}),"actual Main Home from generated selected library");JournalSnapshots.robot=new Robot();JournalSnapshots.robot.setAutoDelay(30);JournalSnapshots.check(JournalSnapshots.edt(FirstRunSetupAcceptance::panel)==null,"Existing generated selected library opens without first-run wizard");for(int width:new int[]{1280,420}){JournalSnapshots.edt(()->{JournalSnapshots.frame.setSize(width,900);return null;});JournalSnapshots.snap("generated-selected-home-"+width);}JournalSnapshots.check(true,"Actual generated-library Main Home captured at1280 and420");
  }catch(Throwable problem){report.add("FAIL: "+problem);problem.printStackTrace();exit=1;}finally{Files.write(JournalSnapshots.out.resolve("report.txt"),report);System.out.println(String.join("\n",report));}System.exit(exit);
 }
}
